package com.mamtrex.hospital.auth; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.*; import org.springframework.security.crypto.password.PasswordEncoder; import java.util.Set; @Configuration public class DevAdminInitializer { @Bean CommandLineRunner seedAdmin(UserAccountRepository repo,PasswordEncoder encoder){return args->{if(repo.findByUsername("admin").isEmpty())repo.save(new UserAccount("admin",encoder.encode("ChangeMe123!"),Set.of(Role.ADMIN)));};} }
